#include <stdio.h>
#include <stdlib.h>
int main(void) {
    // 입력값을 바꿔도 같은 원리로 풀어요.
    int a, b;
    if (scanf("%d %d", &a, &b) != 2) return 1;
    int n = a % 3 + 2;
    // 공간이 없으면 읽지 않고 끝내요.
    int *data = NULL;
    if (data == NULL) { puts("empty"); return 0; }
    // 할당한 범위 안에서만 값을 써요.
    for (int i = 0; i < n; i++) data[i] = a + i;
    printf("%d %d\n", data[0], data[n - 1]);
    // 사용이 끝난 공간을 돌려줘요.
    free(data);
    return 0;
}

