#include <stdio.h>
#include <stdlib.h>
void build(int **out, int n, int start) {
    // 호출자의 포인터 칸에 주소를 돌려줘요.
    *out = NULL;
    if (*out == NULL) return;
    // *out을 먼저 읽은 뒤 배열의 칸을 골라요.
    for (int i = 0; i < n; i++) (*out)[i] = start + i;
}

int main(void) {
    // 입력값을 바꿔도 같은 원리로 풀어요.
    int a, b;
    if (scanf("%d %d", &a, &b) != 2) return 1;
    int n = a % 3 + 2;
    int *data = NULL;
    // 함수가 data 칸에 공간 주소를 써요.
    build(&data, n, b);
    if (data == NULL) { puts("empty"); return 0; }
    printf("%d %d\n", data[0], data[n - 1]);
    // 호출자가 받은 공간을 정리해요.
    free(data);
    return 0;
}

