#include <stdio.h>
int main(void) {
    // 입력값을 바꿔도 같은 원리로 풀어요.
    int a, b;
    if (scanf("%d %d", &a, &b) != 2) return 1;
    int values[3] = {a, b, a + b};
    int *p = values;
    int **pp = &p;
    // 괄호 안의 *pp로 배열 시작을 먼저 얻어요.
    for (int i = 0; i < 3; i++) (*pp)[0] = a + i;
    printf("%d %d %d\n", values[0], values[1], values[2]);
    return 0;
}

